arguments.content:
:root {
  --bg-surface: oklch(98.5% 0.002 265);
  --text-primary: oklch(21% 0.01 265);
  --text-secondary: oklch(45% 0.01 265);
  --text-muted: oklch(60% 0.01 265);
  --brand-accent: oklch(55% 0.17 255);
  --brand-accent-hover: oklch(50% 0.17 255);
  --border-color: oklch(92% 0.01 265);
  --card-bg: oklch(100% 0 0);
  --bg-dark: oklch(20% 0.01 265);

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;

  --container-width: 1200px;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 24px;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.05);
  --shadow-lg: 0 12px 24px rgba(0,0,0,0.08);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-surface);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
  transition: color 0.2s ease;
}

ul {
  list-style: none;
}

.container {
  max-width: var(--container-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

.hidden {
  display: none !important;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 500;
  font-size: 0.875rem;
  cursor: pointer;
  transition: all 0.2s ease;
  border: 1px solid transparent;
}

.btn-primary {
  background-color: var(--text-primary);
  color: var(--bg-surface);
}

.btn-primary:hover {
  background-color: oklch(15% 0 0);
}

.btn-secondary {
  background-color: var(--card-bg);
  color: var(--text-primary);
  border-color: var(--border-color);
}

.btn-secondary:hover {
  background-color: oklch(96% 0.01 265);
}

.btn-outline {
  background-color: transparent;
  color: var(--text-primary);
  border-color: var(--border-color);
}

.btn-outline:hover {
  background-color: var(--card-bg);
}

/* Header */
.site-header {
  position: sticky;
  top: 0;
  background-color: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
  z-index: 100;
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.header-left, .header-right {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 600;
  font-size: 1.125rem;
}

.main-nav {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.nav-link {
  font-size: 0.875rem;
  color: var(--text-secondary);
  font-weight: 500;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem 0;
}

.nav-link:hover, .nav-link.active {
  color: var(--text-primary);
}

.nav-link .arrow {
  font-size: 0.75rem;
  margin-left: 0.25rem;
}

.dropdown {
  position: relative;
}

.mega-menu {
  position: absolute;
  top: 100%;
  left: -20px;
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  padding: 2rem;
  opacity: 0;
  visibility: hidden;
  transform: translateY(10px);
  transition: all 0.2s ease;
  min-width: 600px;
}

.dropdown:hover .mega-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.mega-menu-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.mega-menu.regular-menu .mega-column {
  min-width: 150px;
}
.mega-menu.regular-menu {
  display: flex;
  gap: 2rem;
  min-width: auto;
}

.mega-column h3 {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  margin-bottom: 1rem;
}

.mega-column ul {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.mega-column a {
  display: flex;
  flex-direction: column;
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.mega-column a strong {
  color: var(--text-primary);
  font-weight: 500;
}

.mega-column a span {
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-top: 0.125rem;
}

.mega-column a:hover strong {
  color: var(--brand-accent);
}

/* Hero */
.blog-hero {
  padding: 4rem 0 2rem;
  text-align: center;
}

.blog-hero h1 {
  font-size: 3rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 1rem;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto;
}

/* Filters & Search */
.filters-section {
  margin-bottom: 3rem;
}

.filters-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--border-color);
}

.category-filters {
  display: flex;
  gap: 0.5rem;
  overflow-x: auto;
  padding-bottom: 0.5rem;
  scrollbar-width: none; /* Firefox */
}

.category-filters::-webkit-scrollbar {
  display: none;
}

.filter-pill {
  padding: 0.5rem 1rem;
  border-radius: 99px;
  border: 1px solid var(--border-color);
  background: var(--card-bg);
  color: var(--text-secondary);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s ease;
}

.filter-pill:hover {
  border-color: var(--text-primary);
  color: var(--text-primary);
}

.filter-pill.active {
  background: var(--text-primary);
  color: var(--card-bg);
  border-color: var(--text-primary);
}

.search-container {
  position: relative;
  min-width: 250px;
}

.search-icon {
  position: absolute;
  left: 0.75rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
}

#searchInput {
  width: 100%;
  padding: 0.5rem 1rem 0.5rem 2.5rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
  background: var(--card-bg);
  font-size: 0.875rem;
  font-family: inherit;
  transition: border-color 0.2s;
}

#searchInput:focus {
  outline: none;
  border-color: var(--brand-accent);
}

/* Featured Articles */
.featured-articles {
  margin-bottom: 4rem;
}

.featured-grid {
  display: grid;
  grid-template-columns: 3fr 2fr;
  gap: 1.5rem;
}

.featured-card {
  display: flex;
  flex-direction: column;
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.featured-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.card-content {
  padding: 2rem;
  display: flex;
  flex-direction: column;
  height: 100%;
}

.primary-featured .card-content {
  padding: 3rem;
}

.card-meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.875rem;
  margin-bottom: 1rem;
}

.tag {
  color: var(--brand-accent);
  font-weight: 500;
}

.date {
  color: var(--text-muted);
}

.featured-card h3 {
  font-size: 1.5rem;
  font-weight: 600;
  margin-bottom: 1rem;
  line-height: 1.3;
}

.primary-featured h3 {
  font-size: 2.25rem;
  letter-spacing: -0.02em;
}

.featured-card p {
  color: var(--text-secondary);
  margin-bottom: 1.5rem;
  flex-grow: 1;
}

.primary-featured p {
  font-size: 1.125rem;
}

.agentic-stats {
  display: flex;
  gap: 2rem;
  margin: 1.5rem 0 2.5rem;
  padding: 1.5rem;
  background: var(--bg-surface);
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
}

.stat-item {
  display: flex;
  flex-direction: column;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-primary);
}

.stat-label {
  font-size: 0.75rem;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-top: 0.25rem;
}

.card-author {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.875rem;
  font-weight: 500;
}

.avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 0.75rem;
  font-weight: 600;
}

.bg-blue { background-color: oklch(55% 0.17 255); }
.bg-green { background-color: oklch(65% 0.15 150); }
.bg-orange { background-color: oklch(65% 0.18 45); }
.bg-purple { background-color: oklch(55% 0.2 300); }
.bg-teal { background-color: oklch(60% 0.1 200); }

.secondary-featured {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

/* Latest News */
.latest-news {
  margin-bottom: 6rem;
}

.section-title {
  font-size: 1.5rem;
  font-weight: 600;
  margin-bottom: 2rem;
}

.news-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  margin-bottom: 3rem;
}

.post-card {
  display: flex;
  flex-direction: column;
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1.5rem;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.post-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.post-card h3 {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 0.75rem;
  line-height: 1.4;
}

.post-card p {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  margin-bottom: 1.5rem;
  flex-grow: 1;
}

.no-results {
  text-align: center;
  padding: 4rem 0;
  color: var(--text-muted);
}

.no-results svg {
  margin-bottom: 1rem;
  opacity: 0.5;
}

.no-results h3 {
  color: var(--text-primary);
  font-size: 1.25rem;
  margin-bottom: 0.5rem;
}

.load-more-container {
  text-align: center;
}

/* CTA Banner */
.cta-banner {
  margin-bottom: 6rem;
}

.cta-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  background: var(--text-primary);
  color: white;
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.cta-content {
  padding: 4rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.cta-content h2 {
  font-size: 2.25rem;
  margin-bottom: 1rem;
  letter-spacing: -0.02em;
}

.cta-content p {
  color: var(--border-color);
  font-size: 1.125rem;
  margin-bottom: 2rem;
  max-width: 400px;
}

.cta-actions {
  display: flex;
  gap: 1rem;
}

.cta-actions .btn-primary {
  background: white;
  color: var(--text-primary);
}

.cta-actions .btn-primary:hover {
  background: oklch(95% 0 0);
}

.cta-actions .btn-secondary {
  background: transparent;
  color: white;
  border-color: rgba(255,255,255,0.2);
}

.cta-actions .btn-secondary:hover {
  background: rgba(255,255,255,0.1);
}

.cta-enterprise {
  background: oklch(15% 0.01 265);
  padding: 4rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
}

.cta-enterprise h3 {
  font-size: 1.5rem;
  margin-bottom: 1rem;
}

.cta-enterprise p {
  color: var(--text-muted);
  margin-bottom: 2rem;
}

.cta-enterprise .btn-outline {
  border-color: rgba(255,255,255,0.2);
  color: white;
}

.cta-enterprise .btn-outline:hover {
  background: rgba(255,255,255,0.1);
}

/* Footer */
.site-footer {
  background: var(--card-bg);
  border-top: 1px solid var(--border-color);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 2rem;
  margin-bottom: 4rem;
}

.footer-col h4 {
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 1rem;
}

.footer-col .mt-4 {
  margin-top: 2rem;
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer-col a {
  color: var(--text-secondary);
  font-size: 0.875rem;
}

.footer-col a:hover {
  color: var(--text-primary);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 2rem;
  border-top: 1px solid var(--border-color);
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.footer-logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 500;
  color: var(--text-primary);
}

.footer-status {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.status-indicator {
  width: 8px;
  height: 8px;
  background-color: oklch(55% 0.17 255);
  border-radius: 50%;
}

.footer-social {
  display: flex;
  gap: 1.5rem;
}

.footer-social a:hover {
  color: var(--text-primary);
}

/* Responsive Design */
@media (max-width: 992px) {
  .header-nav {
    display: none;
  }
  .featured-grid {
    grid-template-columns: 1fr;
  }
  .news-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .cta-inner {
    grid-template-columns: 1fr;
  }
  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  .header-left .main-nav, .header-right {
    display: none; /* In a real app we'd have a mobile menu toggle here */
  }
  .news-grid {
    grid-template-columns: 1fr;
  }
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .filters-top {
    flex-direction: column;
    align-items: stretch;
  }
  .search-container {
    width: 100%;
  }
  .agentic-stats {
    flex-direction: column;
    gap: 1rem;
  }
  .footer-bottom {
    flex-direction: column;
    gap: 1rem;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .footer-grid {
    grid-template-columns: 1fr;
  }
  .cta-content, .cta-enterprise {
    padding: 2rem;
  }
  .primary-featured .card-content {
    padding: 1.5rem;
  }
}

